  }
  if (tracker.scanning()) fb_gfx_print(&g, 4, 4, COLOR_YELLOW, "SCAN");
  if (tracker.locked()) fb_gfx_print(&g, fb->width - 14 * 4 - 4, 4, COLOR_RED, "LOCK");
