1	// =============================================================================
2	//  Tracking turret enclosure for Seeed Studio XIAO ESP32S3 Sense + 2x SG90/MG90S
3	//  OpenSCAD 2021.01
4	//
5	//  Parts (select with -D part="<name>"):
6	//    base       pan servo housing, open bottom
7	//    base_lid   bottom cover for the base (4x M2 screws, rubber-foot recesses)
8	//    yoke       pan platform: disc on the pan horn + two arms carrying the tilt axis
9	//    head       camera housing for the XIAO + Sense board (open back)
10	//    head_lid   back cover for the head (friction lip + 2x M2)
11	//    assembly   everything in place with mock servos / board, for preview
12	//    plate      all printable parts laid out flat
13	//
14	//  Coordinate convention (assembly): Z up, camera looks along +X.
15	//  Every part module is authored in assembly position; print_* transforms
16	//  reorient for the bed. Dimensions in mm.
17	// =============================================================================
18	
19	part = "assembly";          // base | base_lid | yoke | head | head_lid | assembly | plate
20	$fn = 64;
21	
22	// ---------------------------------------------------------------- tolerances
23	clr      = 0.30;            // general clearance around inserted parts
24	lip_clr  = 0.25;            // friction-fit lip clearance
25	m2_pilot = 1.75;            // M2 self-tapping pilot hole in PLA/PETG
26	m2_free  = 2.30;            // M2 through hole
27	m3_pilot = 2.60;
28	m3_free  = 3.30;
29	
30	// ------------------------------------------------------ SG90 / MG90S servo
31	// Local servo frame: shaft axis = +Z through (0,0); Z=0 at flange BOTTOM face.
32	sv_l        = 22.8;         // body length (along local X)
33	sv_w        = 12.4;         // body width  (along local Y)
34	sv_h        = 22.7;         // body height, bottom of body to top of body
35	sv_flange_z = 15.9;         // body bottom to flange bottom
36	sv_flange_t = 2.5;
37	sv_flange_l = 32.5;
38	sv_hole_d   = 2.0;
39	sv_hole_sp  = 27.5;         // flange screw hole spacing
40	sv_shaft_off= 5.9;          // shaft axis from the near body end (along X)
41	sv_boss_d   = 11.8;
42	sv_boss_h   = 4.0;
43	sv_spline_d = 4.8;
44	sv_spline_h = 3.2;
45	sv_horn_d   = 21.0;         // round / cross horn envelope
46	sv_horn_t   = 1.8;          // horn plate thickness
47	sv_horn_h   = 3.8;          // boss top to horn plate OUTER face (hub height)
48	sv_cx       = sv_shaft_off - sv_l/2;            // body center X in the local frame (-5.5)
49	sv_top      = sv_h - sv_flange_z;               // body top above flange bottom (6.8)
50	sv_boss_top = sv_top + sv_boss_h;               // 10.8
51	sv_horn_face= sv_boss_top + sv_horn_h;          // 14.6  (horn outer face)
52	horn_pocket = 2.2;                              // recess depth for the horn plate
53	
54	// -------------------------------------------- XIAO ESP32S3 Sense board stack
55	pcb_w        = 17.5;        // board width  (across the two pin rows)
56	pcb_l        = 21.0;        // board length (USB-C on one short edge)
57	stack_h      = 11.0;        // camera lens top  ->  XIAO back face
58	cam_module_h = 5.0;         // camera lens top  ->  expansion PCB top face
59	cam_dz       = 2.0;         // lens center offset from board center toward the antenna end
60	cam_win_d    = 10.0;        // front window diameter
61	usb_slot     = true;        // opening in the head floor for a (right-angle) USB-C plug
62	usb_w        = 13.5;        // USB-C overmold width
63	usb_t        = 7.5;         // USB-C overmold thickness
64	
65	// --------------------------------------------------------------------- head
66	wall      = 2.0;
67	head_iy   = pcb_w + 0.8;                    // 18.3 interior width (tilt axis direction)
68	head_iz   = pcb_l + 4.0;                    // 25.0 interior height
69	head_ix   = stack_h + 3.5;                  // 14.5 interior depth (front inner face -> lid inner face)
70	lid_t     = 2.0;
71	lid_lip   = 3.0;                            // lip depth into the shell
72	lip_t     = 1.4;
73	side_a_t  = wall + 2.5;                     // +Y wall (horn side): 4.5, pocket leaves 2.3
74	side_b_t  = wall + 3.5;                     // -Y wall (pivot side): 5.5, M3 pilot depth 5
75	head_y0   = -(head_iy/2 + side_b_t);        // -14.65
76	head_y1   =  (head_iy/2 + side_a_t);        //  13.65
77	head_z    = head_iz + 2*wall;               // 29
78	head_xlen = wall + head_ix + lid_t;         // 18.5 total incl. lid
79	head_x0   = -head_xlen/2;                   // front face
