95	arm_a_out= arm_a_in + arm_t;
96	arm_b_in = head_y0 - gap_b;                 // arm B inner face (Y), negative
97	arm_b_out= arm_b_in - arm_t;
98	gusset_h = 10;
99	
100	// --------------------------------------------------------------------- base
101	base_d      = 78;
