103	base_wall   = 2.4;
104	base_top_t  = 3.0;
105	base_lid_t  = 2.5;
106	base_boss_d = 6.5;
107	inlet       = true;                         // side cutout for a panel-mount USB-C / DC jack breakout
108	inlet_w     = 13;
109	inlet_h     = 7;
110	cable_hole_d= 12;
111	foot_d      = 10.5;
112	
113	// ------------------------------------------------------------ assembly Z's
114	base_top   = base_h;
115	disc_z0    = base_top + sv_horn_face - horn_pocket;    // disc bottom
116	disc_z1    = disc_z0 + disc_t;
117	axis_z     = disc_z1 + axis_h;
118	
119	// =============================================================================
120	//  helpers
121	// =============================================================================
122	module rrect(w, h, r) { offset(r) offset(-r) square([w, h], center = true); }
123	module cyl_x(d, l) { rotate([0, 90, 0]) cylinder(d = d, h = l, center = true); }
124	module cyl_y(d, l) { rotate([90, 0, 0]) cylinder(d = d, h = l, center = true); }
125	
126	// -------------------------------------------------------------- servo model
127	module servo(mock = false) {
128	  c = mock ? 0 : clr;
129	  color("dimgray") {
130	    // body
131	    translate([sv_cx, 0, (sv_top - sv_flange_z)/2])
