139	  }
140	  if (mock) color("white") {
141	    translate([0, 0, sv_boss_top]) cylinder(d = 7, h = sv_horn_h);
142	    translate([0, 0, sv_horn_face - sv_horn_t]) cylinder(d = sv_horn_d, h = sv_horn_t);
143	  }
144	}
