152	    translate([sv_cx + s*sv_hole_sp/2, 0, pilot_z0]) cylinder(d = m2_pilot, h = pilot_z1 - pilot_z0);
153	  // wire exit relief along the body
154	  translate([sv_cx - sv_l/2 - 2, -4, z0]) cube([3, 8, z1 - z0]);
155	}
