static void px(std::vector<uint8_t>& b, int W, int x, int y, int r, int g, int bl) {
  uint16_t v = ((r >> 3) << 11) | ((g >> 2) << 5) | (bl >> 3);
  b[(y * W + x) * 2] = v >> 8; b[(y * W + x) * 2 + 1] = v & 0xFF;
}
static void scene(std::vector<uint8_t>& b, int W, int H, int tx, int ty) {
  for (int y = 0; y < H; y++) for (int x = 0; x < W; x++) px(b, W, x, y, 120 + (x % 7), 120 + (y % 5), 125);   // gray wall
  for (int y = 20; y < 80; y++) for (int x = 10; x < 70; x++) px(b, W, x, y, 40, 60, 200);                     // blue poster (distractor, same hue)
  for (int y = ty - 25; y < ty + 25; y++) for (int x = tx - 20; x < tx + 20; x++) if (x>=0&&x<W&&y>=0&&y<H) px(b, W, x, y, 30, 80, 210);  // blue shirt
  for (int y = ty - 62; y < ty - 32; y++) for (int x = tx - 12; x < tx + 12; x++) if (x>=0&&x<W&&y>=0&&y<H) px(b, W, x, y, 220, 170, 140); // face
}
int main() {
