  std::vector<uint8_t> buf(W * H * 2);
  camera_fb_t fb{buf.data(), buf.size(), W, H, PIXFORMAT_RGB565};
  ColorTracker ct;
  scene(buf, W, H, 120, 150);
  ct.init(&fb, 120, 150, 40, 50, -0.3f);
  int fails = 0;
  int path[][2] = {{128,150},{140,148},{155,145},{170,150},{185,160},{200,170},{205,175},{190,170},{160,160},{130,150},{100,140},{80,135}};
  for (auto& p : path) {
    scene(buf, W, H, p[0], p[1]);
    Target t;
    bool ok = ct.track(&fb, t);
    int ex = t.x - p[0], ey = t.y - p[1];
    bool good = ok && abs(ex) <= 4 && abs(ey) <= 4;
    if (!good) fails++;
    printf("truth (%3d,%3d)  track %s (%3d,%3d) %dx%d conf=%.2f aimY=%d %s\n", p[0], p[1], ok ? "ok " : "LOST", t.x, t.y, t.w, t.h, ct.confidence(), ct.aimY(), good ? "" : "<-- BAD");
  }
