  printf("target removed: track %s conf=%.2f at (%d,%d) %s\n", ok ? "ok" : "lost", ct.confidence(), t.x, t.y, ok ? "<-- BAD (false positive)" : "");
  if (ok) fails++;
  printf("%s\n", fails ? "FAIL" : "PASS");
