7	void Tracker::begin() {
8	  pinMode(PIN_LASER, OUTPUT);
9	  digitalWrite(PIN_LASER, LOW);
10	  _panServo.attach(PIN_SERVO_PAN, LEDC_CH_PAN, PAN_MIN_DEG, PAN_MAX_DEG);
11	  _tiltServo.attach(PIN_SERVO_TILT, LEDC_CH_TILT, TILT_MIN_DEG, TILT_MAX_DEG);
12	  loadSettings();
13	  _pan = _panSet = PAN_CENTER_DEG;
14	  _tilt = _tiltSet = TILT_CENTER_DEG;
15	  _panServo.writeDeg(_pan + settings.panTrim);
16	  _tiltServo.writeDeg(_tilt + settings.tiltTrim);
17	  _lastMoveMs = millis();
18	}
