20	float Tracker::clampPan(float v) const { return v < PAN_MIN_DEG ? PAN_MIN_DEG : (v > PAN_MAX_DEG ? PAN_MAX_DEG : v); }
21	float Tracker::clampTilt(float v) const { return v < TILT_MIN_DEG ? TILT_MIN_DEG : (v > TILT_MAX_DEG ? TILT_MAX_DEG : v); }
