23	void Tracker::setMode(Mode m) {
24	  _mode = m;
25	  _locked = false;
26	  _onTargetSince = 0;
27	  _scanning = (m == MODE_SCAN);
28	  _lastSeenMs = 0;
29	  if (m == MODE_SCAN) _tiltSet = clampTilt(settings.scanTilt);
30	}
31	
32	bool Tracker::aimPoint(int& x, int& y) const {
33	  if (!_last.found) return false;
34	  x = _last.x;
35	  if (_last.kind == TARGET_FACE) y = _last.y + (int)(settings.aimBelow * _last.w);
36	  else if (_last.kind == TARGET_TORSO && torsoAimY >= 0) y = torsoAimY;
37	  else y = _last.y;
38	  return true;
39	}
40	
41	void Tracker::onDetection(const Target& t, uint32_t nowMs) {
42	  _last = t;
43	  if (_mode != MODE_FACE && _mode != MODE_MOTION) return;
44	
45	  if (t.found) {
46	    _lastSeenMs = nowMs;
47	    _scanning = false;
48	    int ax, ay;
49	    aimPoint(ax, ay);
50	    float exPx = (float)ax - CAM_W / 2.0f;
51	    float eyPx = (float)ay - CAM_H / 2.0f;
52	    float ex = exPx / (CAM_W / 2.0f);
53	    float ey = eyPx / (CAM_H / 2.0f);
54	    float dead = (float)settings.deadbandPx;
55	
56	    // Proportional correction outside the deadband; keeps running while locked so a
57	    // slowly moving target is followed without dropping the lock.
58	    if (fabsf(exPx) > dead) {
59	      // Target right of center: pan toward it. Direction depends on servo mounting.
60	      _panSet = clampPan(_panSet + settings.kp * ex * (settings.invertPan ? -1.0f : 1.0f));
61	    }
62	    if (fabsf(eyPx) > dead) {
63	      // Target above center (ey < 0): tilt up. Default: larger angle = up.
64	      _tiltSet = clampTilt(_tiltSet + settings.kp * (-ey) * (settings.invertTilt ? -1.0f : 1.0f));
65	    }
66	
67	    bool inside = fabsf(exPx) <= dead && fabsf(eyPx) <= dead;
68	    float rel = dead * (settings.lockRelease < 1.0f ? 1.0f : settings.lockRelease);
69	    bool outsideRelease = fabsf(exPx) > rel || fabsf(eyPx) > rel;
70	
71	    if (_locked) {
72	      if (outsideRelease) {          // hysteresis: only a large excursion breaks the lock
73	        _locked = false;
74	        _onTargetSince = 0;
75	      }
76	    } else if (inside) {
77	      if (!_onTargetSince) _onTargetSince = nowMs;
78	      _locked = (nowMs - _onTargetSince) >= (uint32_t)settings.lockMs;
79	    } else {
80	      _onTargetSince = 0;
81	    }
82	  } else {
83	    _locked = false;
84	    _onTargetSince = 0;
85	    if (settings.scanWhenLost && _lastSeenMs && (nowMs - _lastSeenMs) > (uint32_t)settings.lostMs) {
86	      _scanning = true;
87	    }
88	    if (settings.scanWhenLost && !_lastSeenMs) {
89	      _scanning = true;  // never seen anything since mode change
90	    }
91	  }
92	}
93	
94	void Tracker::tick(uint32_t nowMs) {
95	  float dt = _lastTickMs ? (nowMs - _lastTickMs) / 1000.0f : (1.0f / CONTROL_HZ);
96	  _lastTickMs = nowMs;
97	  if (dt > 0.2f) dt = 0.2f;
98	
99	  if (_scanning && (_mode == MODE_SCAN || _mode == MODE_FACE || _mode == MODE_MOTION)) {
100	    _panSet += _scanDir * settings.scanSpeed * dt;
101	    if (_panSet >= PAN_MAX_DEG) { _panSet = PAN_MAX_DEG; _scanDir = -1; }
102	    if (_panSet <= PAN_MIN_DEG) { _panSet = PAN_MIN_DEG; _scanDir = 1; }
103	    if (_mode == MODE_SCAN) _tiltSet = clampTilt(settings.scanTilt);
104	  }
105	
106	  auto step = [&](float cur, float set) {
107	    float e = (set - cur) * settings.smooth;
108	    if (e > settings.maxStep) e = settings.maxStep;
109	    if (e < -settings.maxStep) e = -settings.maxStep;
110	    if (fabsf(set - cur) < 0.05f) e = set - cur;
111	    return e;
112	  };
113	  float dp = step(_pan, _panSet);
114	  float dtl = step(_tilt, _tiltSet);
115	  _pan += dp;
116	  _tilt += dtl;
117	  _panServo.writeDeg(_pan + settings.panTrim);
118	  _tiltServo.writeDeg(_tilt + settings.tiltTrim);
119	
120	  _moving = (fabsf(dp) > 0.08f) || (fabsf(dtl) > 0.08f);
121	  if (_moving) _lastMoveMs = nowMs;
122	
123	  applyLaser();
124	}
