"""Render a Claude Code session JSONL into a readable Markdown transcript."""
import json, sys, datetime, os

src, out = sys.argv[1], sys.argv[2]
MAX_RESULT = 1500      # chars of tool output kept per call
MAX_INPUT = 800        # chars of tool input kept per call

def ts(rec):
    t = rec.get("timestamp")
    if not t:
        return ""
    try:
        return datetime.datetime.fromisoformat(t.replace("Z", "+00:00")).astimezone().strftime("%H:%M:%S")
    except Exception:
        return str(t)

def clip(s, n):
    s = s if isinstance(s, str) else json.dumps(s, ensure_ascii=False)
    return s if len(s) <= n else s[:n] + f"\n... [{len(s) - n} more chars]"

lines = ["# Turret project session transcript", "",
         f"Source: `{os.path.basename(src)}`  ", f"Rendered: {datetime.datetime.now():%Y-%m-%d %H:%M}", ""]
n_user = n_asst = n_tool = 0
for raw in open(src, encoding="utf-8"):
    raw = raw.strip()
    if not raw:
        continue
    try:
        rec = json.loads(raw)
    except Exception:
        continue
    typ = rec.get("type")
    msg = rec.get("message") or {}
    content = msg.get("content")
    if typ not in ("user", "assistant") or content is None:
        continue
    if isinstance(content, str):
        content = [{"type": "text", "text": content}]
    for block in content:
        bt = block.get("type")
        if bt == "text":
            text = block.get("text", "").strip()
            if not text:
                continue
            if typ == "user":
                if text.startswith("<") and ("system-reminder" in text[:40] or "local-command" in text[:40]):
                    continue
                n_user += 1
                lines += [f"## User  `{ts(rec)}`", "", text, ""]
            else:
                n_asst += 1
                lines += [f"## Claude  `{ts(rec)}`", "", text, ""]
        elif bt == "thinking":
            continue
        elif bt == "tool_use":
            n_tool += 1
            name = block.get("name", "?")
            inp = block.get("input", {})
            desc = inp.get("description") if isinstance(inp, dict) else None
            head = f"**Tool: {name}**" + (f" — {desc}" if desc else "")
            shown = {k: v for k, v in inp.items() if k not in ("description",)} if isinstance(inp, dict) else inp
            if isinstance(shown, dict) and "content" in shown and isinstance(shown["content"], str) and len(shown["content"]) > MAX_INPUT:
                shown = dict(shown, content=clip(shown["content"], MAX_INPUT))
            lines += [head, "", "```json", clip(json.dumps(shown, ensure_ascii=False, indent=1), MAX_INPUT * 2), "```", ""]
        elif bt == "tool_result":
            c = block.get("content")
            if isinstance(c, list):
                c = "\n".join(x.get("text", "") for x in c if isinstance(x, dict) and x.get("type") == "text")
            c = (c or "").strip()
            if not c:
                continue
            lines += ["<details><summary>result</summary>", "", "```", clip(c, MAX_RESULT), "```", "", "</details>", ""]

lines += ["---", f"{n_user} user messages, {n_asst} assistant messages, {n_tool} tool calls."]
open(out, "w", encoding="utf-8").write("\n".join(lines))
print(f"wrote {out}: {n_user} user, {n_asst} assistant, {n_tool} tool calls, {os.path.getsize(out)} bytes")

